def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    hr = next((r for r in range(h)
               if grid[r][0] != bg and all(x == grid[r][0] for x in grid[r])), None)
    if hr is not None:
        # Place the stripe two rows from the divider, on the side containing
        # the non-background object.
        obj_rows = [r for r in range(h) for c in range(w) if grid[r][c] not in (bg, grid[hr][0])]
        direction = 1 if sum(obj_rows) / len(obj_rows) > hr else -1
        stripe = hr + 2 * direction
        if 0 <= stripe < h:
            out[stripe] = [8] * w
        return out

    vc = next((c for c in range(w)
               if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))), None)
    if vc is not None:
        obj_cols = [c for r in range(h) for c in range(w) if grid[r][c] not in (bg, grid[0][vc])]
        direction = 1 if sum(obj_cols) / len(obj_cols) > vc else -1
        stripe = vc + 3 * direction
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    return out
